#include <iostream>
#include <iomanip>

int main() {
    double a = 0.0, b = 0.0;
    char op = 0;
    if (std::cin >> a >> b >> op) {
        double result = 0.0;
        bool valid = true;
        switch (op) {
            case '+':
                result = a + b;
                break;
            case '-':
                result = a - b;
                break;
            case '*':
            case 'x':
            case '.':
                result = a * b;
                break;
            case '/':
            case ':':
                if (b != 0.0) {
                    result = a / b;
                } else {
                    valid = false;
                }
                break;
            default:
                valid = false;
                break;
        }
        if (valid) {
            std::cout << std::fixed << std::setprecision(4);
            std::cout << "Ket qua la: " << result << "\n";
        } else {
            std::cout << "Phep toan khong hop le\n";
        }
    }
    return 0;
}

